        await owner.Database.MigrateAsync();var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Omlx:Model","controlled-semantic-model"}}).Build();await using var db=new Database(new DbContextOptionsBuilder<Database>().UseNpgsql(owner.Database.GetConnectionString()).Options,config);
        var (actor,p)=await BuilderSemanticPreparationCases.Seed(db);await db.Families.Where(f=>f.Id==actor.FamilyId).ExecuteUpdateAsync(u=>u.SetProperty(f=>f.OwnerAccountId,actor.AccountId));db.ChangeTracker.Clear();
        await using var lease=await BackgroundJobs.Claim(db,types:[BuilderSemanticJobs.Type],inputRef:p.Id)??throw new Exception("No preparation lease");var frozen=Json.Read<BuilderSemanticFrozenInput>(p.Snapshot);var input=Json.Read<BuilderSemanticInput>(frozen.ModelInputPayload);var model=BuilderSemanticJobs.ResolveLocal(frozen);
        var library=await db.Releases.SingleAsync(r=>r.Id==p.LibraryReleaseId);await Publishing.Register(db,library);var catalog=Json.Read<Catalog>(library.Payload);var draft=new ContentDraft{FamilyId=p.FamilyId,Title="Controlled shared-budget mapping fixture",Payload=library.Payload};db.Add(draft);await db.SaveChangesAsync();var question=catalog.Questions[0];var selection=new MappingOwnerSelection("Question",question.Id,question.RevisionId);
        var mapping=await MappingJobs.Enqueue(db,actor,new(draft.Id,library.Id,[selection],"LocalOmlx"));await db.SaveChangesAsync();await using var mappingLease=await BackgroundJobs.Claim(db,types:[MappingJobs.Type],inputRef:mapping.Id)??throw new Exception("No real mapping lease");var mappingFrozen=Json.Read<MappingFrozenInput>(mapping.Snapshot);var mappingModel=MappingJobs.ResolveLocal(mappingFrozen);var mappingInput=MappingModelProtocol.Capture(catalog,draft.Id,[selection],catalog.Kcs);var mappingNever=new NeverMapping();
        var paused=new Paused();var pending=new BuilderSemanticCallTracking(db,p,model,lease,paused).Generate(input,lease.Token);await paused.Started.Task.WaitAsync(TimeSpan.FromSeconds(8));
        await using(var writer=BackgroundJobs.Open(owner))using(var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(3)))await using(var tx=await writer.Database.BeginTransactionAsync(deadline.Token)){await writer.Lock(p.FamilyId,deadline.Token);writer.Audits.Add(new(){FamilyId=p.FamilyId,Action="SemanticProviderConcurrentWrite",Details="provider is still waiting"});await writer.SaveChangesAsync(deadline.Token);await tx.CommitAsync(deadline.Token);}
        var never=new Never();await Denied(()=>new BuilderSemanticCallTracking(db,p,model,lease,never).Generate(input,lease.Token),"BUILDER_CONCURRENCY_LIMIT");Check(never.Calls==0,"Semantic concurrency denial still called provider");await Denied(()=>new MappingModelCallTracking(db,mapping,mappingModel,mappingLease,mappingNever).Generate(mappingInput,mappingLease.Token),"BUILDER_CONCURRENCY_LIMIT");Check(mappingNever.Calls==0,"Mapping bypassed active semantic slot");
        await using(var builder=BackgroundJobs.Open(owner)){var denied=new BuilderCall{FamilyId=p.FamilyId,RunId=p.RunId,ExecutionId=Guid.NewGuid(),AttemptNumber=1,CallNumber=1,Provider="Mock",Model="fixture/1",InputHash=Content.Hash("controlled shared slot")};Check(await BuilderBudget.Reserve(builder,denied,BuilderQuote.Local,CancellationToken.None)=="BUILDER_CONCURRENCY_LIMIT","Builder bypassed active semantic slot");}
        paused.Release.TrySetResult();var response=await pending;Check(!response.OutputComplete,"Truncated response changed");var call=await db.Set<BuilderSemanticCall>().AsNoTracking().SingleAsync(c=>c.PreparationId==p.Id && c.Status=="Returned");Check(call.InputTokens==13 && call.OutputTokens==7 && call.BudgetState=="Settled" && call.ErrorCode=="LOCAL_PROVIDER_OUTPUT_INCOMPLETE","Real truncated return/usage not independently saved");Check(call.InputPayload==frozen.ModelInputPayload && call.ModelConfigPayload==frozen.ModelConfigPayload,"Frozen call provenance lost");
        await using(var tx=await db.Database.BeginTransactionAsync()){db.Audits.Add(new(){FamilyId=p.FamilyId,Action="SemanticUncommittedBusinessResult",Details="controlled rollback"});await db.SaveChangesAsync();await tx.RollbackAsync();}db.ChangeTracker.Clear();Check(await db.Set<BuilderSemanticCall>().AnyAsync(c=>c.Id==call.Id && c.Status=="Returned") && !await db.Audits.AnyAsync(a=>a.Action=="SemanticUncommittedBusinessResult"),"Business rollback erased independent call");
        try{await db.Set<BuilderSemanticCall>().Where(c=>c.Id==call.Id).ExecuteUpdateAsync(u=>u.SetProperty(c=>c.InputTokens,(long?)999));throw new Exception("Returned usage rewritten");}catch(Npgsql.PostgresException e){Check(e.SqlState=="23514","Wrong original call protection");}
        var failure=new Paused(true);var unknown=new BuilderSemanticCallTracking(db,p,model,lease,failure).Generate(input,lease.Token);await failure.Started.Task.WaitAsync(TimeSpan.FromSeconds(8));failure.Release.TrySetResult();try{await unknown;throw new Exception("Unknown provider failure accepted");}catch(IOException){}
        var failed=await db.Set<BuilderSemanticCall>().AsNoTracking().SingleAsync(c=>c.PreparationId==p.Id && c.Status=="Failed");Check(failed.InputTokens==null && failed.OutputTokens==null && failed.ChargedCost==null && (await BuilderBudget.State(db,p.FamilyId,failed.BudgetDay)).ActiveCalls==1,"Unknown call fabricated zeros or released slot");
        await Denied(()=>new BuilderSemanticCallTracking(db,p,model,lease,never).Generate(input,lease.Token),"BUILDER_CONCURRENCY_LIMIT");
        await using(var tx=await db.Database.BeginTransactionAsync()){await Denied(()=>BuilderSemanticCallTracking.Reconcile(db,actor,failed.Id,new(false,null,null,"未确认结束","受控记录")),"RECONCILIATION_REQUIRED");await tx.RollbackAsync();}
        await using(var tx=await db.Database.BeginTransactionAsync()){await BuilderSemanticCallTracking.Reconcile(db,actor,failed.Id,new(true,null,null,"已观察受控失败任务结束","受控提供者已抛出异常并完成任务"));await db.SaveChangesAsync();await tx.CommitAsync();}
        db.ChangeTracker.Clear();Check((await BuilderBudget.State(db,p.FamilyId,failed.BudgetDay)).ActiveCalls==0 && (await db.Set<BuilderSemanticCall>().SingleAsync(c=>c.Id==failed.Id)).InputTokens==null,"Append reconciliation changed original unknown values");
        await using(var tx=await db.Database.BeginTransactionAsync()){await Denied(()=>BuilderSemanticCallTracking.Reconcile(db,actor,failed.Id,new(true,null,null,"重复","重复")),"CALL_ALREADY_RESOLVED");await tx.RollbackAsync();}
        try{await db.Set<BuilderSemanticReconciliation>().Where(r=>r.CallId==failed.Id).ExecuteUpdateAsync(u=>u.SetProperty(r=>r.Reason,"覆盖原依据"));throw new Exception("Reconciliation rewritten");}catch(Npgsql.PostgresException e){Check(e.SqlState=="23514","Wrong append-only decision protection");}
        var mappingPaused=new PausedMapping();var mappingPending=new MappingModelCallTracking(db,mapping,mappingModel,mappingLease,mappingPaused).Generate(mappingInput,mappingLease.Token);await mappingPaused.Started.Task.WaitAsync(TimeSpan.FromSeconds(8));await Denied(()=>new BuilderSemanticCallTracking(db,p,model,lease,never).Generate(input,lease.Token),"BUILDER_CONCURRENCY_LIMIT");mappingPaused.Release.TrySetResult();await mappingPending;
        // Reverse direction: a real durable Builder start holds the same shared slot.
        BuilderCall active=new(){FamilyId=p.FamilyId,RunId=p.RunId,ExecutionId=Guid.NewGuid(),AttemptNumber=1,CallNumber=1,Provider="Mock",Model="fixture/1",InputHash=Content.Hash("controlled active builder")};await using(var builder=BackgroundJobs.Open(owner))Check(await BuilderBudget.Reserve(builder,active,BuilderQuote.Local,CancellationToken.None)==null,"Could not reserve controlled builder start");await Denied(()=>new BuilderSemanticCallTracking(db,p,model,lease,never).Generate(input,lease.Token),"BUILDER_CONCURRENCY_LIMIT");
        Check(await db.Candidates.Where(c=>c.Id==p.CandidateId).Select(c=>c.Status).SingleAsync()=="Pending","Call ledger changed human review state");
        Console.WriteLine("PASS real PG semantic independent starts/returns/unknown failures and append-only owner reconciliation; two-way shared Builder and Mapping budget denial, no family lock during controlled provider wait, raw truncated usage retained across business rollback, original facts immutable; no actual model calls");
    }
