        var receipt=Environment.GetEnvironmentVariable("SEMANTIC_CRASH_RECEIPT")??throw new Exception("Actual observed process termination evidence required");var actor=new Actor(Guid.NewGuid(),preparation.FamilyId,preparation.RequestedBy,null,"Parent","Parent,ContentEditor");
